func (s *DocumentStore[R]) ListByOwner(ctx context.Context, ownerID int64) ([]domain.Document, domain.OperationStats, error) {
	return s.list(ctx, "list", func(query *bun.SelectQuery) *bun.SelectQuery {
		return s.table.whereOwner(query, ownerID).Where(`"document".deleted_at IS NULL`).OrderExpr(`"document".created_at DESC, "document".id DESC`)
	})
}

func (s *DocumentStore[R]) ListDeletedPendingCleanupByOwner(ctx context.Context, ownerID int64) ([]domain.Document, domain.OperationStats, error) {
	return s.list(ctx, "list deleted pending cleanup by owner", func(query *bun.SelectQuery) *bun.SelectQuery {
		return s.table.whereOwner(query, ownerID).Where(`"document".deleted_at IS NOT NULL`).Where(`"document".file_deleted_at IS NULL`).OrderExpr(`"document".id ASC`).Limit(domain.RequestCleanupRetryLimit)
	})
}

func (s *DocumentStore[R]) ListPendingCleanupByOwner(ctx context.Context, ownerID int64) ([]domain.Document, domain.OperationStats, error) {
	return s.list(ctx, "list pending cleanup", func(query *bun.SelectQuery) *bun.SelectQuery {
		return s.table.whereOwner(query, ownerID).Where(`"document".file_deleted_at IS NULL`).OrderExpr(`"document".id ASC`)
	})
}

func (r *CleanupRetention) DeleteRemovedFiles(ctx context.Context) (int, int, error) {
	deleted, err := r.store.DeleteRemovedFiles(ctx, domain.RemovedFileRetentionWindow)
	if err != nil {
		return 0, 0, err
	}
	return deleted, int(domain.RemovedFileRetentionWindow.Hours() / 24), nil
}

func (i IdentityAdapter) ListShareableRoles(ctx context.Context) ([]filestorage.AudienceRole, error) {
	roles, err := i.Module.ListSchoolRoles(ctx)
	if err != nil {
		return nil, err
	}
	result := make([]filestorage.AudienceRole, 0, len(roles))
	for _, role := range roles {
		if role == nil || role.Name == "guardian" || (role.BaseRole != nil && *role.BaseRole == "guardian") {
			continue
		}
		result = append(result, filestorage.AudienceRole{ID: role.ID, Name: role.Name})
	}
	return result, nil
}

